#!/usr/bin/env node
/**
 * Applies the release version — and, when a keystore is supplied, a release
 * signing config — to the Capacitor-generated Android project.
 *
 * `apps/android/android/` is git-ignored and regenerated by `cap add android`, so
 * Capacitor's `versionCode 1` / `versionName "1.0"` would otherwise ship in every
 * APK: Android refuses to install a build whose versionCode is not higher than the
 * installed one, so a release could never update an earlier one.
 *
 * Usage:
 *   node apps/android/scripts/configure-android-project.mjs --version 0.3.0
 *   node apps/android/scripts/configure-android-project.mjs --version 0.3.0 \
 *     --keystore /path/release.jks --store-password "$PW" --key-alias k --key-password "$KPW"
 */
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { parseArgs } from "node:util";

const MARKER = "// --- generated by configure-android-project.mjs ---";

const { values } = parseArgs({
  options: {
    project: { type: "string" },
    version: { type: "string" },
    keystore: { type: "string" },
    "store-password": { type: "string" },
    "key-alias": { type: "string" },
    "key-password": { type: "string" },
  },
});

const fail = (message) => {
  console.error(message);
  process.exit(1);
};

if (!values.version) fail("Missing --version.");

const version = values.version.trim().replace(/^v/, "");
const parsed = /^(\d+)\.(\d+)\.(\d+)(-[0-9A-Za-z.-]+)?$/.exec(version);
if (!parsed) fail(`Not a semver release version: ${values.version}`);

const major = Number(parsed[1]);
const minor = Number(parsed[2]);
const patch = Number(parsed[3]);
// major*10000 + minor*100 + patch keeps versionCode monotonic for any sane tag and
// leaves room for 99 patch releases per minor.
if (minor > 99 || patch > 99) {
  fail(`Cannot encode ${version} as a versionCode (minor and patch must be below 100).`);
}
const versionCode = major * 10000 + minor * 100 + patch;
if (versionCode < 1) fail(`${version} maps to versionCode ${versionCode}, which is not valid.`);

/** Groovy double-quoted string literal. */
const groovyString = (value) =>
  `"${value.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\$/g, "\\$")}"`;

const signing = {
  keystore: values.keystore,
  storePassword: values["store-password"],
  keyAlias: values["key-alias"],
  keyPassword: values["key-password"],
};
const signingKeys = Object.keys(signing);
const providedSigning = signingKeys.filter((key) => Boolean(signing[key]));
if (providedSigning.length > 0 && providedSigning.length < signingKeys.length) {
  fail("Release signing needs --keystore, --store-password, --key-alias and --key-password.");
}
const signRelease = providedSigning.length === signingKeys.length;
const keystorePath = signRelease ? resolve(signing.keystore) : null;
if (keystorePath && !existsSync(keystorePath)) fail(`Keystore not found: ${keystorePath}`);

const shellDir = dirname(fileURLToPath(import.meta.url));
const projectRoot = resolve(values.project ?? join(shellDir, "..", "android"));
const gradleFile = join(projectRoot, "app", "build.gradle");
if (!existsSync(gradleFile)) {
  fail(`Not a Capacitor Android project: ${gradleFile} does not exist.`);
}

const lines = [
  MARKER,
  `// versionName "${version}" -> versionCode ${versionCode}`,
  "android {",
  "    defaultConfig {",
  `        versionCode ${versionCode}`,
  `        versionName ${groovyString(version)}`,
  "    }",
];

if (signRelease) {
  lines.push(
    "    signingConfigs {",
    "        release {",
    `            storeFile file(${groovyString(keystorePath)})`,
    `            storePassword ${groovyString(signing.storePassword)}`,
    `            keyAlias ${groovyString(signing.keyAlias)}`,
    `            keyPassword ${groovyString(signing.keyPassword)}`,
    "        }",
    "    }",
    "    buildTypes {",
    "        release {",
    "            signingConfig signingConfigs.release",
    "        }",
    "    }",
  );
}

lines.push("}", "");

// Re-running must not stack duplicate blocks: drop anything from the marker on.
const gradle = readFileSync(gradleFile, "utf8");
const base = gradle.split(MARKER)[0].trimEnd();
writeFileSync(gradleFile, `${base}\n\n${lines.join("\n")}`, "utf8");

console.log(
  `Set versionName ${version} / versionCode ${versionCode}` +
    (signRelease ? " with release signing" : " (debug-signed build)"),
);
console.log(`Patched ${gradleFile}`);
